"""Whole-system task map drawn like the task explorer (tasks.html): every multi-callback task is laid out with the
explorer's own layered layout (task_viz.layout) inside its block, the blocks are placed in stage columns (longest path
over the links between tasks), and the links between tasks (polled reads / held pointers / state links, the sampled
dependencies) are drawn callback to callback across the blocks — dashed; candidates (no evidence) dotted red.

  <prefix>_full.svg/.png    the same picture before the breakdown: no frames, one node style, every edge solid grey
  <prefix>_tasks.svg/.png   the breakdown: task frames + colours, trigger edges solid, links between tasks dashed (= the cuts)
  <prefix>.html             both views in one page with hover (a block highlights its links)

usage: system_map_svg.py <fish_tasks.json> -o <prefix> [--no-candidates] [--all-singles] [--png-scale 1.0]"""
import argparse, collections, html, json, os, subprocess, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'postprocess'))
import task_viz  # noqa: E402
from task_viz import layout, short_node, short_ent  # noqa: E402

# compact node geometry for the map (the explorer uses 204 x 40)
task_viz.NW, task_viz.NH, task_viz.GX, task_viz.GY, task_viz.PAD = 150, 32, 36, 7, 10
NW, NH = task_viz.NW, task_viz.NH
HB = 20          # block header
BP = 8           # block padding
CGX, CGY = 110, 26   # gaps between columns / blocks
FILLS = ['#dbe9fb', '#fbe3d8', '#d7f1e6', '#fbeec9', '#e3dff8', '#f9e2ec', '#dbf1f5', '#efe8cf', '#e5ebd8', '#f4e0d0', '#dfe8f1', '#f1dcea', '#dfecda', '#f6ead3', '#e8e2f6', '#d8ecE6', '#f3e0da', '#e2e8ee', '#ede6d9', '#dbe9f6']
STROKES = ['#2a78d6', '#eb6834', '#1baf7a', '#d99a00', '#6250d6', '#e87ba4', '#1a8fa3', '#9a7b1a', '#5a7a2a', '#c0652b', '#3a6ea5', '#a04a86', '#4d8a3a', '#b4862c', '#6f5fb3', '#2f8c7a', '#b05a46', '#4b6c86', '#8a7a4e', '#3b7cb8']
INK, INK2, MUTED, GRID, RED, AMBER = '#0b0b0b', '#52514e', '#898781', '#e1e0d9', '#d93a36', '#d98c00'


def ms(ns):
    return '' if ns is None else (f'{ns / 1e6:.1f} ms' if ns < 1e8 else f'{ns / 1e9:.2f} s')


def esc(s):
    return html.escape(str(s), quote=True)


def build_block(t, VT):
    """nodes / edges / layout of one task exactly like task_viz.main (stimulus publishers become one source node per topic)."""
    vids = {v['id'] for v in t['vertices']}
    nodes, edges = [], []
    for v in t['vertices']:
        r = v.get('resource') or {}; T_cfg = (v.get('arrival') or {}).get('T_cfg')
        kind = 'gpu' if v.get('gpu') else 'mt' if r.get('mode') == 'MT' else 'st'
        nodes.append(dict(id=v['id'], k=kind, a=short_node(v['node'], 20), b=short_ent(v['etype'], v['entity'], T_cfg, 18), C=(v.get('C') or {}).get('p50'),
                          join=(v.get('join') or {}).get('role'), name=v['name']))
    for e in t['edges']:
        if not (e.get('n_pairs') or e['kind'] == 'join'): continue
        u = e['u']
        if u not in vids:
            u = f"s{e['u']}:{e['topic']}"
            if not any(n['id'] == u for n in nodes):
                nodes.append(dict(id=u, k='src', a=short_node(str(e['topic']), 20), b='bag stimulus', C=None, join=None, name=f"stimulus {e['topic']}"))
        if e['v'] not in vids: continue
        edges.append(dict(u=u, v=e['v'], kind=e['kind'], topic=e['topic'], n=e.get('n_pairs') or 0, d50=(e.get('delta') or {}).get('p50'), prov=e.get('prov')))
    xy, w, h = layout(nodes, edges)
    for n in nodes: n['x'], n['y'] = xy[n['id']]
    return nodes, edges, w, h


def ns_of(node):
    return (node or '/').strip('/').split('/')[0] or 'other'


def stage_of(t):
    """the namespace of the task's source callback (its timer, or the first subscriber a stimulus triggers) — used only for placement"""
    vid = {v['id']: v for v in t['vertices']}
    for sr in t.get('sources') or []:
        if sr.get('vertex') in vid: return ns_of(vid[sr['vertex']].get('node'))
    return ns_of(t['vertices'][0].get('node'))


def order_stages(stages, W, forced):
    """left-to-right order of the stage columns: --stages if given, else a Kahn-style order (fewest incoming crossings first) so that
    most crossings between namespaces point forward (for Autoware this yields sensing -> localization -> perception -> planning -> control)"""
    rest = set(stages); out = [x for x in forced if x in rest]
    for x in out: rest.discard(x)
    while rest:       # next column = the stage with the fewest crossings coming IN from the stages not placed yet (tie: most going out); isolated stages last
        best = min(sorted(rest), key=lambda a: (0 if (sum(W[a].values()) + sum(W[b][a] for b in W)) else 1,
                                                 sum(W[b][a] for b in rest if b != a), -sum(W[a][b] for b in rest if b != a)))
        out.append(best); rest.discard(best)
    return out


def place(blocks, link_pairs, T, forced_stages):
    """stage columns (namespace order, see order_stages); inside a column the blocks are stacked in barycenter order of the
    blocks they are linked to (4 sweeps), so that links between neighbouring columns stay short."""
    stage = {tid: stage_of(T[tid]) for tid in blocks}
    W = collections.defaultdict(collections.Counter)
    for (u, v), n in link_pairs.items():
        if u in blocks and v in blocks and stage[u] != stage[v]: W[stage[u]][stage[v]] += n
    for tid in blocks:            # namespace crossings INSIDE tasks (trigger edges) order the columns too: sensing -> perception is such a crossing
        vn = {v['id']: ns_of(v.get('node')) for v in T[tid]['vertices']}
        for e in T[tid]['edges']:
            if e['u'] in vn and e['v'] in vn and vn[e['u']] != vn[e['v']] and (e.get('n_pairs') or e['kind'] == 'join'): W[vn[e['u']]][vn[e['v']]] += 1
    order = order_stages(set(stage.values()) | {k for k in W} | {b for k in W for b in W[k]}, W, forced_stages)
    order = [o for o in order if o in set(stage.values())]; col = {tid: order.index(stage[tid]) for tid in blocks}
    cols = collections.defaultdict(list)
    for tid in sorted(blocks, key=lambda i: (-blocks[i]['size'], i)): cols[col[tid]].append(tid)
    nb = collections.defaultdict(collections.Counter)
    for (u, v), n in link_pairs.items():
        if u in blocks and v in blocks and u != v: nb[u][v] += n; nb[v][u] += n
    pos = {tid: i for c in cols for i, tid in enumerate(cols[c])}

    def centre(tid):      # fractional position inside its column, block heights taken into account
        c = cols[col[tid]]; acc = 0
        for x in c:
            if x == tid: return acc + blocks[x]['H'] / 2
            acc += blocks[x]['H'] + CGY
        return acc
    for sweep in range(4):
        rng = sorted(cols) if sweep % 2 == 0 else sorted(cols, reverse=True)
        for c in rng:
            def key(tid):
                ns = [(centre(o), n) for o, n in nb[tid].items() if col[o] != c]
                return (sum(y * n for y, n in ns) / sum(n for _, n in ns)) if ns else centre(tid)
            ks = {tid: key(tid) for tid in cols[c]}; cols[c].sort(key=lambda tid: ks[tid])
    X = 20; XY = {}
    heights = {c: sum(blocks[u]['H'] for u in cols[c]) + CGY * (len(cols[c]) - 1) for c in cols}
    Hmax = max(heights.values()); colx = {}
    for c in sorted(cols):
        Wc = max(blocks[u]['W'] for u in cols[c]); y = 40 + (Hmax - heights[c]) / 2; colx[c] = (X, Wc)
        for u in cols[c]:
            XY[u] = (X, y); y += blocks[u]['H'] + CGY
        X += Wc + CGX
    return XY, X - CGX + 20, Hmax + 60, col, order, colx


def bez(x1, y1, x2, y2):
    back = x2 <= x1; dx = 60 if back else max(24, (x2 - x1) / 2)
    return f'M{x1:.0f},{y1:.0f} C{x1 + dx:.0f},{y1:.0f} {x2 - dx:.0f},{y2:.0f} {x2 - 1:.0f},{y2:.0f}'


def main():
    ap = argparse.ArgumentParser(); ap.add_argument('json'); ap.add_argument('-o', '--out', required=True)
    ap.add_argument('--no-candidates', action='store_true'); ap.add_argument('--all-singles', action='store_true'); ap.add_argument('--png-scale', type=float, default=1.0)
    ap.add_argument('--stages', default='', help='comma-separated left-to-right order of the namespace columns (default: derived from the link directions)')
    ap.add_argument('--link-labels', action='store_true', help='print topic · age on every link line in the SVG (the HTML shows them on hover)')
    a = ap.parse_args()
    d = json.load(open(a.json)); data = [t for t in d['tasks'] if not t.get('infra')]
    T = {t['id']: t for t in data}; VT = {v['id']: t['id'] for t in data for v in t['vertices']}
    multi = {t['id'] for t in data if t['size'] > 1}
    links = [s for s in d['sampled'] if s.get('method') not in ('tf_lookup', 'tf_static') and s['reader_vertex'] in VT]
    pairs = collections.defaultdict(list)
    for s in links:
        for wt in (s.get('writer_tasks') or []):
            if wt in T and wt != s['reader_task']: pairs[(wt, s['reader_task'])].append(s)
    cands = [] if a.no_candidates else [c for c in d['candidates'] if c['u'] in VT and c['v'] in VT and VT[c['u']] != VT[c['v']]]
    cpairs = collections.defaultdict(list)
    for c in cands: cpairs[(VT[c['u']], VT[c['v']])].append(c)
    allp = set(pairs) | set(cpairs)
    shown = multi | ({t['id'] for t in data} if a.all_singles else {t for p in allp for t in p if any(x in multi for x in p)})
    # blocks
    blocks = {}
    for tid in shown:
        nodes, edges, w, h = build_block(T[tid], VT)
        src = T[tid]['sources'][0]['name'] if T[tid]['sources'] else T[tid]['vertices'][0]['name']
        src = src.split('→')[-1].strip() if '→' in src else src
        blocks[tid] = dict(nodes=nodes, edges=edges, w=w, h=h, W=w + 2 * BP, H=h + HB + 2 * BP, size=T[tid]['size'], title=f"task {tid} · {short_node(src, 36)} · {T[tid]['size']} cb")
    XY, CW, CH, col, order, colx = place(blocks, {p: len(v) for p, v in pairs.items() if p[0] in shown and p[1] in shown}, T, [x for x in a.stages.split(',') if x] if a.stages else [])
    color = {tid: i % len(FILLS) for i, tid in enumerate(sorted(shown, key=lambda i: (col[i], XY[i][1])))}
    # absolute node positions
    P = {}
    for tid, b in blocks.items():
        bx, by = XY[tid]
        for n in b['nodes']: P[(tid, n['id'])] = (bx + BP + n['x'], by + HB + BP + n['y'])
    pub_in_task = collections.defaultdict(set)
    for t in data:
        for e in t['edges']:
            if e.get('topic') and e['u'] in VT and VT[e['u']] == t['id']: pub_in_task[(t['id'], e['topic'])].add(e['u'])

    def anchor(wt, s):
        wv = s.get('writer_vertex')
        if wv is not None and VT.get(wv) == wt: return wv
        pubs = pub_in_task.get((wt, s.get('topic')))
        if pubs: return min(pubs)
        for sr in T[wt]['sources']:
            if VT.get(sr.get('vertex')) == wt: return sr['vertex']
        return T[wt]['vertices'][0]['id']
    # links callback -> callback, merged per (u, v)
    L = collections.defaultdict(lambda: dict(n=0, topics=collections.Counter(), ages=[], w=None, r=None))
    for (wt, rt), lst in pairs.items():
        if wt not in shown or rt not in shown: continue
        for s in lst:
            u = anchor(wt, s); k = (u, s['reader_vertex']); x = L[k]; x['n'] += 1; x['w'], x['r'] = wt, rt
            x['topics'][s.get('topic') or s.get('method') or 'state'] += 1
            if s.get('age_p50'): x['ages'].append(s['age_p50'])
    CL = collections.defaultdict(lambda: dict(n=0, w=None, r=None, ptr=0))
    for (wt, rt), lst in cpairs.items():
        if wt not in shown or rt not in shown: continue
        for c in lst:
            k = (c['u'], c['v']); CL[k]['n'] += 1; CL[k]['w'], CL[k]['r'] = wt, rt
            if str(c.get('candidate_evidence') or '').startswith('pointer'): CL[k]['ptr'] += 1
    n_cand_all = len(d['candidates']); n_cand_live = sum(1 for c in d['candidates'] if c['u'] in VT and c['v'] in VT)
    n_cand_ptr = sum(1 for c in d['candidates'] if c['u'] in VT and c['v'] in VT and str(c.get('candidate_evidence') or '').startswith('pointer'))
    n_cols = max(col.values()) + 1
    title = (f"FISH task map — session {d['session']}: {len(shown)} data tasks ({len(multi)} with >1 callback), columns = namespaces ordered by link direction ({' → '.join(order)}); "
             f"{sum(x['n'] for x in L.values())} links between tasks (polled reads / held pointers), {sum(x['n'] for x in CL.values())} candidates drawn ({n_cand_live} live of {n_cand_all})")

    def legend(y0, br):
        """drawn legend panel: node anatomy, the three edge classes, block / column meaning (monospace 11 px ~ 6.7 px per character)"""
        cw = 6.7
        L = [f'<g font-size="11" fill="{INK2}">', f'<rect x="20" y="{y0}" width="1720" height="{164 if br else 56}" rx="8" fill="#ffffff" stroke="{GRID}"/>']
        x, y = 34, y0 + 12
        t1, t2 = 'callback: node · entity (subscription topic / timer period / service)', 'right: median execution time C · "join" = waits for several inputs'
        L.append(f'<rect x="{x}" y="{y}" width="{NW}" height="{NH}" rx="6" fill="#ffffff" stroke="#c3c2b7"/><text x="{x + 7}" y="{y + 13}" font-size="9.5" fill="{INK}">node</text>'
                 f'<text x="{x + 7}" y="{y + 25}" font-size="8.5" fill="{INK2}">sub topic / timer T</text><text x="{x + NW - 6}" y="{y + 25}" font-size="8.5" fill="{INK2}" text-anchor="end">C p50</text>')
        L.append(f'<text x="{x + NW + 10}" y="{y + 12}">{esc(t1)}</text><text x="{x + NW + 10}" y="{y + 26}">{esc(t2)}</text>')
        xs = x + NW + 10 + max(len(t1), len(t2)) * cw + 28
        s1, s2 = 'stimulus: a message the rosbag player publishes', '(the source of a task without a timer)'
        L.append(f'<rect x="{xs:.0f}" y="{y}" width="{NW}" height="{NH}" rx="6" fill="#ffffff" stroke="#c3c2b7" stroke-dasharray="3 3"/><text x="{xs + 7:.0f}" y="{y + 13}" font-size="9.5" fill="{INK}">topic</text><text x="{xs + 7:.0f}" y="{y + 25}" font-size="8.5" fill="{INK2}">bag stimulus</text>')
        L.append(f'<text x="{xs + NW + 10:.0f}" y="{y + 12}">{esc(s1)}</text><text x="{xs + NW + 10:.0f}" y="{y + 26}">{esc(s2)}</text>')
        if not br:
            xe = xs + NW + 10 + max(len(s1), len(s2)) * cw + 28
            L.append(f'<text x="{xe:.0f}" y="{y + 12}">edges: every observed pairing drawn in one style — the dense graph</text><text x="{xe:.0f}" y="{y + 26}">before the breakdown (compare with the tasks view)</text></g>')
            return '\n'.join(L)
        rows = [[(INK2, '', 'url(#ah)', 'trigger edge inside a task: identity-paired (DDS reader-cache record, intra-process address)'),
                 (MUTED, ' stroke-dasharray="2 4"', '', 'join tie: the callback waits for several inputs (message_filters, container op, method probe)'),
                 (INK2, ' stroke-dasharray="6 4"', 'url(#ah)', 'service request / response (request id)')],
                [(INK2, ' stroke-dasharray="7 5"', 'url(#ah)', 'link between tasks = a cut: a timer / callback reads the LATEST value another task produced (polled read, held pointer, state link); hover: topic · age p50 · ×links')],
                [(AMBER, ' stroke-dasharray="2 4"', 'url(#aha)', f'candidate with a held pointer ({n_cand_ptr}): message still alive when the reader published; deposit is a field / copy = latest value'),
                 (RED, ' stroke-dasharray="2 4"', 'url(#ahr)', f'candidate, structural only ({n_cand_live - n_cand_ptr}): sub callback stores, a publishing callback of the same node may read; no runtime record')],
                [(None, '', '', f'{n_cand_all} candidates in the session: {n_cand_live} between callbacks active in the window (drawn when both tasks are shown), {n_cand_all - n_cand_live} involve a callback that ran < 5 times (not drawn). Candidates never connect tasks.')]]
        y = y0 + 64
        for row in rows:
            xx = 34
            for col_, dash, mk, txt in row:
                if col_: L.append(f'<path d="M{xx:.0f},{y} L{xx + 34:.0f},{y}" fill="none" stroke="{col_}" stroke-width="1.6"{dash} marker-end="{mk}"/>')
                L.append(f'<text x="{xx + 42:.0f}" y="{y + 4}">{esc(txt)}</text>')
                xx += 42 + len(txt) * cw + 26
            y += 20
        tt = 'task = one FISH task (frame colour): callbacks tied by identity-paired trigger edges; title = id · source · callback count'
        L.append(f'<rect x="34" y="{y - 9}" width="34" height="14" rx="4" fill="{FILLS[0]}" stroke="{STROKES[0]}" stroke-width="1.2"/><text x="76" y="{y + 4}">{esc(tt)}</text>')
        xc = 76 + len(tt) * cw + 26
        L.append(f'<text x="{xc:.0f}" y="{y + 4}"><tspan font-weight="600">column</tspan> = namespace of the task\'s source callback, ordered by crossing direction (placement only)</text></g>')
        return '\n'.join(L)

    def svg(kind):
        br = kind == 'tasks'
        LH = 210 if br else 100     # legend panel height
        o = [f'<svg xmlns="http://www.w3.org/2000/svg" width="{CW:.0f}" height="{CH + LH:.0f}" viewBox="0 0 {CW:.0f} {CH + LH:.0f}" font-family="ui-monospace, Menlo, Consolas, DejaVu Sans Mono, monospace">',
             '<defs><marker id="ah" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto"><path d="M0,0.5 L7.5,4 L0,7.5 z" fill="#52514e"/></marker>'
             '<marker id="ahr" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto"><path d="M0,0.5 L7.5,4 L0,7.5 z" fill="#d93a36"/></marker><marker id="aha" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto"><path d="M0,0.5 L7.5,4 L0,7.5 z" fill="#d98c00"/></marker></defs>',
             f'<rect width="100%" height="100%" fill="#fcfcfb"/>',
             f'<text x="20" y="{CH + 24:.0f}" font-size="13" fill="{INK}">{esc(title)}{"" if br else " — before the breakdown: one dense graph, every edge the same"}</text>']
        o.append(legend(CH + 34, br))
        if br:
            for c, (cx, cw) in colx.items():
                o.append(f'<text x="{cx + cw / 2:.0f}" y="24" font-size="13" font-weight="600" fill="{INK2}" text-anchor="middle">{esc(order[c])}</text>')
        for tid, b in blocks.items():
            bx, by = XY[tid]; f, s = (FILLS[color[tid]], STROKES[color[tid]]) if br else ('none', 'none')
            o.append(f'<g class="blk" data-t="{tid}">')
            if br:
                o.append(f'<rect x="{bx:.0f}" y="{by:.0f}" width="{b["W"]:.0f}" height="{b["H"]:.0f}" rx="9" fill="{f}" stroke="{s}" stroke-width="1.2"/>')
                o.append(f'<text x="{bx + BP:.0f}" y="{by + 14:.0f}" font-size="11" font-weight="600" fill="{s}">{esc(b["title"])}</text>')
            for e in b['edges']:
                a1, b1 = P[(tid, e['u'])], P[(tid, e['v'])]
                st = {'intra': MUTED, 'join': MUTED}.get(e['kind'], INK2) if br else INK2
                dash = ' stroke-dasharray="2 4"' if (br and e['kind'] == 'join') else (' stroke-dasharray="6 4"' if (br and e['kind'].startswith('srv')) else '')
                o.append(f'<path d="{bez(a1[0] + NW, a1[1] + NH / 2, b1[0], b1[1] + NH / 2)}" fill="none" stroke="{st}" stroke-width="1.3"{dash} marker-end="url(#ah)"><title>{esc(e["topic"] or e["kind"])} · {e["kind"]} · {esc(e["prov"])} · n={e["n"]} · {ms(e["d50"])}</title></path>')
            for n in b['nodes']:
                x, y = P[(tid, n['id'])]
                sd = ' stroke-dasharray="3 3"' if n['k'] == 'src' else ''
                o.append(f'<g><rect x="{x:.0f}" y="{y:.0f}" width="{NW}" height="{NH}" rx="6" fill="#ffffff" stroke="#c3c2b7"{sd}/>'
                         f'<text x="{x + 7:.0f}" y="{y + 13:.0f}" font-size="9.5" fill="{INK}">{esc(n["a"])}</text>'
                         f'<text x="{x + 7:.0f}" y="{y + 25:.0f}" font-size="8.5" fill="{INK2}">{esc(n["b"])}{" · join" if n.get("join") else ""}</text>'
                         + (f'<text x="{x + NW - 6:.0f}" y="{y + 25:.0f}" font-size="8.5" fill="{INK2}" text-anchor="end">{ms(n["C"])}</text>' if n['C'] else '') + f'<title>{esc(n["name"])}</title></g>')
            o.append('</g>')
        # links between tasks
        for (u, v), x in L.items():
            if (x['w'], u) not in P or (x['r'], v) not in P: continue
            a1, b1 = P[(x['w'], u)], P[(x['r'], v)]; top = x['topics'].most_common(1)[0][0]; ages = sorted(x['ages'])
            lab = f"{short_ent('sub', top, None, 24)[4:]}{(' · ' + ms(ages[len(ages) // 2])) if ages else ''}{(' ×%d' % x['n']) if x['n'] > 1 else ''}"
            dash = ' stroke-dasharray="7 5"' if br else ''
            o.append(f'<path class="lnk" data-w="{x["w"]}" data-r="{x["r"]}" d="{bez(a1[0] + NW, a1[1] + NH / 2, b1[0], b1[1] + NH / 2)}" fill="none" stroke="{INK2}" stroke-width="1.1"{dash} opacity="0.85" marker-end="url(#ah)"><title>{esc(lab)} — {", ".join(esc(k) for k in x["topics"])}</title></path>')
            if br:
                mx, my = (a1[0] + NW + b1[0]) / 2, (a1[1] + b1[1]) / 2 + NH / 2
                vis = '' if a.link_labels else ' visibility="hidden"'
                o.append(f'<text class="lnk lab"{vis} data-w="{x["w"]}" data-r="{x["r"]}" x="{mx:.0f}" y="{my - 3:.0f}" font-size="8.5" fill="{INK2}" text-anchor="middle" paint-order="stroke" stroke="#fcfcfb" stroke-width="3">{esc(lab)}</text>')
        for (u, v), x in CL.items():
            if (x['w'], u) not in P or (x['r'], v) not in P: continue
            a1, b1 = P[(x['w'], u)], P[(x['r'], v)]
            cd = ' stroke-dasharray="2 4"' if br else ''
            ptr = x['ptr'] > 0; colr = (AMBER if ptr else RED) if br else INK2; mk = ('aha' if ptr else 'ahr') if br else 'ah'
            tip = f'candidate ×{x["n"]}: ' + ('message pointer still held when the reader published (latest-value deposit, source says field/object)' if ptr else 'structural rule only (sub callback stores, this callback of the node publishes), no runtime record')
            o.append(f'<path class="lnk cand" data-w="{x["w"]}" data-r="{x["r"]}" d="{bez(a1[0] + NW, a1[1] + NH / 2, b1[0], b1[1] + NH / 2)}" fill="none" stroke="{colr}" stroke-width="1.0"{cd} opacity="0.8" marker-end="url(#{mk})"><title>{esc(tip)}</title></path>')
        o.append('</svg>')
        return '\n'.join(o)
    outs = {}
    for kind in ('full', 'tasks'):
        s = svg(kind); fn = f'{a.out}_{kind}.svg'; open(fn, 'w').write(s); outs[kind] = s
        r = subprocess.run([sys.executable, os.path.join(os.path.dirname(os.path.abspath(__file__)), 'svg2png.py'), fn, f'{a.out}_{kind}.png', str(a.png_scale)], capture_output=True, text=True)
        print(fn, f'{a.out}_{kind}.png' if r.returncode == 0 else f'png failed: {r.stderr[-200:]}')
    page = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><title>FISH task map {esc(d["session"])}</title>
<style>body{{margin:0;background:#f9f9f7;font-family:system-ui,sans-serif;color:#0b0b0b}} .bar{{position:sticky;top:0;background:#fcfcfb;border-bottom:1px solid #e1e0d9;padding:8px 14px;display:flex;gap:14px;align-items:center;font-size:13px;z-index:2}}
button{{font:inherit;border:1px solid #c3c2b7;background:#fff;border-radius:999px;padding:4px 12px;cursor:pointer}} button[aria-pressed=true]{{border-color:#0b0b0b;box-shadow:inset 0 0 0 1px #0b0b0b}}
.wrap{{overflow:auto}} svg{{display:block}} .dim{{opacity:0.08}} .hl{{stroke-width:2.2 !important;opacity:1 !important;visibility:visible !important}}</style></head><body>
<div class="bar"><strong>FISH task map</strong> <span>{esc(d["session"])}</span> <button id="bf" aria-pressed="false">before the breakdown (dense graph)</button> <button id="bt" aria-pressed="true">the breakdown (tasks + cuts)</button> <span style="color:#52514e">hover a task block to isolate its links</span></div>
<div class="wrap" id="w"></div>
<script>const V={{full:{json.dumps(outs["full"])},tasks:{json.dumps(outs["tasks"])}}};const w=document.getElementById('w');
function show(k){{w.innerHTML=V[k];document.getElementById('bf').setAttribute('aria-pressed',k==='full');document.getElementById('bt').setAttribute('aria-pressed',k==='tasks');
for(const g of w.querySelectorAll('g.blk')){{g.addEventListener('mouseenter',()=>{{const t=g.dataset.t;for(const l of w.querySelectorAll('.lnk')){{const on=l.dataset.w===t||l.dataset.r===t;l.classList.toggle('hl',on);l.classList.toggle('dim',!on);}}}});g.addEventListener('mouseleave',()=>{{for(const l of w.querySelectorAll('.lnk')){{l.classList.remove('hl','dim');}}}});}}}}
document.getElementById('bf').onclick=()=>show('full');document.getElementById('bt').onclick=()=>show('tasks');show('tasks');</script></body></html>'''
    open(f'{a.out}.html', 'w').write(page)
    print(f'{a.out}.html  canvas {CW:.0f}x{CH:.0f}, {len(shown)} blocks in {n_cols} columns, {len(L)} link lines ({sum(x["n"] for x in L.values())} links), {len(CL)} candidate lines')


if __name__ == '__main__':
    main()
